(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["aussie"] = {"ui":{"skip":"Skip to the good bit","back":"← Back to AI-gile","lang.button":"Language: {name}","lang.dialog":"Pick a language, mate","lang.search":"Search languages","lang.none":"No language matches that","lang.notYet":"{name} hasn't been translated yet","theme.aria":"Switch between light and dark theme","theme.toLight":"Switch to light theme","theme.toDark":"Switch to dark theme","index.title":"AI-gile: your AI dev team, on one board","index.description":"AI-gile is a kanban board for AI coding teams. They work while you're having a snooze; you get one short pile of things to decide, test and accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Your AI dev team, on one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and a bit rough: ta for giving it a go!","hero.lede":"They build while you sleep. You wake up to one short pile: a few questions, a few things to test, a purple diamond or two. Click, accept, back to your cuppa.","dl.windows":"Windows app","dl.browser":"Run it in your browser","dl.soon":"Coming soon","dl.notify":"🔔 Give me a yell when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the team never needs a stand-up coffee. (They do stand-ups anyway, the keen beans.)","pitch.h2":"AI-gile in as many words as you reckon","pitch.lede":"Pick a length, from one word to 144. Each length is its own description, written for that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another go","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card on the board right now","count.line.html.other":"{n} cards on the board right now","features.aria":"What it does","f.pile.h":"One pile for you","f.pile.html":"<b>For you</b> holds everything waiting on you, across every project: questions, things to test, jobs only a human can do. Your queue says what's next and how long it'll take.","f.sleep.h":"Teams that work while you sleep","f.sleep.p":"Each project has a lead and a team of AI agents. Comment on a card and the team wakes up, does the work, and hands it back with steps a knackered human can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Before anything reaches you, a tester follows the steps in a copy of the app and shows what it saw, with a screenshot. Flick through the ones that passed and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over shows what changed: the files, the diff, the screenshots. No opening every app to see if it's done.","f.chat.h":"Chat with your leads","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds for what needs you. Message a lead an idea; they turn it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keeps itself tidy","f.tidy.p":"Related cards fold into one, muddled titles get fixed, and a token check keeps the code lean. Fewer things to juggle, less to think about.","f.private.h":"Yours, on your computer","f.private.li1":"The board runs on your own machine and only answers to you.","f.private.li2":"Private DMs between mates are end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In your language","f.lang.p":"Over 120 languages, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick switch back to English for the developer words.","tl.aria":"Timeline from the first yarn to the roadmap","tl.h2":"From the first yarn to what's next","tl.lede":"Real dates and times, in your own time zone. After today it's the plan, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Jump in","join.lede":"AI-gile is being built by one small human and heaps of patient agents. It's private for now, in a closed alpha with mates. Keen for a go when it opens up?","join.btn":"Register interest","join.small":"We'll email you, nothing else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","form.sending":"Sending…","form.failed":"That didn't work: have another go later.","form.offline":"Couldn't reach AI-gile: have another go later.","interest.title":"AI-gile: give me a yell when the alpha opens","interest.description":"Leave your email to hear when AI-gile's closed alpha or beta opens.","interest.h1":"🔔 Give me a yell when it opens","interest.lede":"AI-gile is in closed pre-alpha. Leave your email and we'll write once, when there's a spot for you.","interest.email":"Your email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, heaps of changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Pop me on the list","interest.thanks":"Ta! You're on the list.","interest.kept":"Only your email and the test you picked are kept, for this list only. No newsletter, no trackers.","licence.title":"AI-gile: business licence","licence.description":"Using AI-gile in your business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Using AI-gile at work? Tell us who you are and what you do. If it does some good, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"What you do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Ta! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"All quiet, no worries","status.checking":"Having a look…","status.offline":"Can't reach the status service right now (trying again)","status.updated":"updated {ago}","status.justNow":"just now","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","live.h2":"Watch it bein' built, live, mate","live.caption":"Every card's hidden: ya see the shape of the work, not the words.","live.watching.one":"live: {n} watchin'","live.watching.other":"live: {n} watchin'","live.offline":"The live board's havin' a bit of a breather, mate. Check back soon.","live.cols":"Backlog|To do|In progress|Team checking|For you to test|For the team|Done"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Sorted."]},{"n":2,"texts":["Robot kanban.","Agents, sorted.","Ideas, built."]},{"n":3,"texts":["Kanban for robots.","Ideas become features.","Free agent kanban."]},{"n":5,"texts":["Kanban board run by agents.","You write cards. Agents build.","Free, local, tested, a bit daft."]},{"n":8,"texts":["Free kanban board where AI agents do the yakka.","Write an idea. Agents build it. You say righto.","Agile for one human and heaps of patient robots."]},{"n":13,"texts":["A kanban board on your own computer where AI agents grab the cards.","Write an idea. A team of agents builds it. A tester gives it a once-over.","Free, no accounts, no trackers: a board, some robots, and you running the show."]},{"n":21,"texts":["AI-gile is a kanban board for working with AI coding agents. They grab the cards; you test them and say yes.","Each project gets a lead and a team of AI agents. Comment on any card and the team gets stuck in.","A free, personal to-do board that runs on your own computer. The workers are robots. The one saying yes is you."]},{"n":34,"texts":["You put ideas on a board. A team of AI agents turns them into working features, tests them, and hands them back with steps to try. Nothing counts as done until you give the nod.","AI-gile is a homemade kanban board that Rich built with a fair bit of help from the agents it now looks after. It's free, runs on your computer, and gets shared with mates, not sold.","Picture a normal kanban board, with columns from Backlog to Done, except the cards get picked up by AI agents. They report progress, sing out when they're stuck, and always wait for your thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board where the team is made of AI agents. Each project has a lead who plans the work and helpers who build it. When a feature's ready, an AI tester has a go and takes a screenshot, then it lands in your pile. Accept it, or comment and they do it over.","It started as one bloke's way of keeping track of heaps of AI coding sessions at once, and grew into a proper board. It runs on your machine, needs no account, and has no trackers. It's free for mates and anyone curious. It's also unfinished, so expect a few rough edges and the odd surprise.","Here's the honest version. You still need to come up with the ideas, and you still need to check the results. What AI-gile does is everything in between: it keeps the cards in order, wakes the right agent when you comment, shows exactly what changed, and keeps the lot in one short pile for you."]},{"n":89,"texts":["AI-gile is a free kanban board that you run on your own computer. Instead of people, each project has a team of AI agents: a lead who turns your ideas into cards and a plan, and helpers who pick the cards up in priority order. When something's built, an AI tester follows the test steps and shows you what it saw. Then it waits in one pile marked For you. You accept it, or you comment and the team has another crack. Nothing ever gets to Done without you.","A few features you mightn't expect. A night watch keeps the To do column topped up while you're asleep, picking cards that don't need an answer from you. A token counter shows how much the agents have used today and this week, and No Token Mode tells them to stop spending. You can message your mates, and private messages are end-to-end encrypted. The board speaks about 120 languages, including Dutch, Flemish, pirate and Klingon. None of it costs a cent, and nobody's trying to flog it to you either.","AI-gile is a small, personal project, not a company. Rich wanted to look after a few AI coding projects without opening every app to check on them, so he and the agents built a board for it, then used the board to build the rest of itself. It's in closed pre-alpha, which means it works, mostly, for a handful of mates. There's no pricing page, no newsletter and no growth plan. If it sounds handy, you can ask for a go when it opens up a bit more."]},{"n":144,"texts":["AI-gile is a kanban board for one human and a heap of AI agents. It runs on your own computer and it's completely free. You add projects, and each project gets a lead and a small team. You chat with the lead, a bit like Discord, and describe an idea; the lead turns it into cards and a plan, then waits for you to press Go. The team works through the cards in priority order, using a simple command line made for language models. Before anything comes back to you, an AI tester follows the steps in a copy of the app and attaches a screenshot. Finished work lands in your pile with the changed files and the diff. You accept it, or you leave a comment and the team wakes up and has another go. Only you can move a card to Done.","A day with AI-gile, roughly. In the evening you leave a few comments: this button's in the wrong spot, that list should be sorted, could we have a dark mode. You go to bed. The agents read the comments, make the changes, test them and hand them back to you. If To do runs dry, the night watch tops it up from the backlog with cards that need no answer from you. In the morning there's one short pile: a couple of questions and a few things to try, each with steps a sleepy person can follow and a screenshot of it working. You click through, accept the good ones and send back the rest. A token counter shows what it all used, and No Token Mode is there for lean weeks. Then you have brekkie, which the agents can't help with yet.","First, what AI-gile isn't. It isn't a startup, it isn't for sale, and nobody's collecting your data. It's a free board that runs on your computer, with no accounts, no trackers and no cookies. What it is: one tidy place to see every AI coding project at once, with a team of agents doing the cards and you making the decisions. It folds related cards together, fixes muddled titles, and keeps an eye on how lean the code stays. It speaks about 120 languages, from Dutch and Flemish to pirate and Klingon. Mates can message each other, privately and encrypted. It was built by Rich and a whole lot of patient agents, mostly using itself. It's in closed pre-alpha, so it's rough in spots. If it sounds like fun, ask nicely and you might get in early."]}],"quips":{"1":"One word. Bold. Maybe a bit too bold.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths are story points, by the way. Course they are.","55":"Fifty-five words. Two cards got finished while you read that.","144":"That's the long one. There's no 233. The agents have knocked off for the arvo."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first yarn, before there was a single line of code.","first-board.name":"First board","first-board.line":"A board that tracks its own build: cards, columns, drag and drop, projects.","team-roles.name":"Team and roles","team-roles.line":"Agent profiles, team templates, spaces and who does what.","install.name":"Install and releases","install.line":"A zip a mate can install, self-updates, channels and rolling back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, make your limit last.","friends.name":"Mates and sharing","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Languages","languages.line":"Every screen text in a language file, with Dutch and Flemish first off the rank.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks every hand-over first and shows what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board for folks who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the teams on task while you're off in dreamland.","p-more.name":"Everything else","p-more.line":"Smaller ideas still waiting their turn.","p-android.name":"Phone and Android","p-android.line":"Get to your board from a phone, then a proper Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More languages","p-languages.line":"More than a hundred languages, and an immersion mode for learners.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex or Gemini for each agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Looking after you","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and planning for growth.","p-livestream.name":"Streaming extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."}};
